<?php
/** TEMP PS S1686 nb — 3 ETAPAS: Sender testinė kampanija į PS_TEST (terra). f=info — paskutinės kampanijos from/reply_to, grupė; f=kurti — POST /campaigns su CALC prototipu (deploy/relaunch/relaunch-calc-v0.2.html, base64) ; f=siusti&id=X — POST /campaigns/{id}/send. */
add_action('init', function(){
  if (!isset($_GET['ps_s1686nb'])) return; $o=array('v'=>'S1686 nb'); $f=$_GET['ps_s1686nb'];
  $tok=Petshop_Sender_Adapter::get_stored_token('marketing');
  $api=function($m,$p,$b=null) use($tok){ $a=array('method'=>$m,'timeout'=>25,'headers'=>array('Authorization'=>'Bearer '.$tok,'Accept'=>'application/json','Content-Type'=>'application/json')); if($b!==null) $a['body']=wp_json_encode($b);
    $r=wp_remote_request('https://api.sender.net/v2'.$p,$a); if(is_wp_error($r)) return array('code'=>0,'err'=>$r->get_error_message()); return array('code'=>wp_remote_retrieve_response_code($r),'body'=>json_decode(wp_remote_retrieve_body($r),true)); };
  $HTML=base64_decode('');
  if($f==='info'){ $r=$api('GET','/campaigns?limit=3'); foreach((array)($r['body']['data']??array()) as $c) $o['kamp'][]=array_intersect_key($c,array_flip(array('id','title','subject','from','reply_to','status','sent_time'))); $o['grupe']=$api('GET','/groups/bDxp2q')['body']['data']??null; }
  elseif($f==='kurti'){ $r=$api('GET','/campaigns?limit=1'); $last=$r['body']['data'][0]??array(); $from=$_GET['from']??($last['from']??'info@petshop.lt'); $reply=$_GET['reply']??($last['reply_to']??$from);
    $b=array('title'=>'TEST relaunch CALC v0.2 '.date('m-d H:i'),'subject'=>'Maišas {{PS_HERO_KAINA}}. O diena?','from'=>$from,'reply_to'=>$reply,'content_type'=>'html','content'=>$HTML,'groups'=>array('bDxp2q'),'preheader'=>'Kiek kainuoja viena diena? Suskaičiavome pagal jūsų maistą.');
    $c=$api('POST','/campaigns',$b); $id=$c['body']['data']['id']??''; $o['kurti']=array('code'=>$c['code'],'id'=>$id,'msg'=>$c['body']['message']??null,'errors'=>$c['body']['errors']??null,'from'=>$from,'reply'=>$reply);
    $g=$api('GET','/groups/bDxp2q')['body']['data']??array(); $o['grupe_aktyviu']=$g['active_subscribers']??null; if($id && (int)($g['active_subscribers']??0)===1){ $s=$api('POST','/campaigns/'.$id.'/send'); $o['send']=array('code'=>$s['code'],'msg'=>$s['body']['message']??$s['body']); } else $o['send']='praleista'; }
  elseif($f==='siusti'){ $o['siusti']='naudok kurti'; }
  header('Content-Type: application/json; charset=utf-8'); echo json_encode($o,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT); exit;
});
